function startAutomaticFlip(){if(window.innerWidth<=767){var t=document.getElementById("pic-front"),e=document.getElementById("pic-back"),n=!0;setInterval(function(){n?(t.style.transform="rotateY(-180deg)",e.style.transform="rotateY(0deg)"):(t.style.transform="rotateY(0deg)",e.style.transform="rotateY(180deg)"),n=!n},5e3)}}function openLightbox(t){document.getElementById("lightbox-image").src=t,document.getElementById("lightbox").style.display="block"}function closeLightbox(){document.getElementById("lightbox").style.display="none"}function fadeInElements(){const t=document.querySelector(".section__text-mobile"),e=document.querySelector(".btn-container-mobile");t.classList.add("visible"),e.classList.add("visible"),t.addEventListener("transitionend",function(){t.style.opacity="1"}),e.addEventListener("transitionend",function(){e.style.opacity="1"})}function voltarParaOTopo(){window.scrollTo({top:0,behavior:"smooth"})}document.addEventListener("DOMContentLoaded",startAutomaticFlip),document.addEventListener("DOMContentLoaded",function(){fadeInElements()});const animationContainer=document.getElementById("lottie-animation"),animationData={container:animationContainer,renderer:"svg",loop:!0,autoplay:!0,path:"start.json"},animacao=lottie.loadAnimation(animationData);